import subprocess
def run(inp:bytes):
    r=subprocess.run(["./executable"], input=inp, capture_output=True)
    return r.returncode, r.stdout, r.stderr
for kind, fmt in [
 ("double", lambda e: b'"a'+e+b'b";'),
 ("single", lambda e: b"'a"+e+b"b';"),
 ("raw", lambda e: b"`a"+e+b"b`;"),
]:
    ok=[]
    for code in range(32,127):
        esc=b'\\'+bytes([code])
        rc,out,err=run(fmt(esc))
        if rc==0:
            ok.append((chr(code), out.rstrip(b'\n')))
    print(kind, ok)
# \u variants in raw?
for fmt_name, fmt in [("double", lambda e: b'"a'+e+b'b";'),("single", lambda e: b"'a"+e+b"b';"),("raw", lambda e: b"`a"+e+b"b`;")]:
    for e in [b'\\u1234', b'\\u123', b'\\u12345', b'\\x41']:
        rc,out,err=run(fmt(e))
        print(fmt_name, e, rc, out)
