import os, subprocess, pty, select, time
def run_pty(stream_tty, args, inp=b""):
    # stream_tty: dict which streams use tty slave
    masters={}
    slaves={}
    kwargs={}
    for name in ['stdin','stdout','stderr']:
        if stream_tty.get(name):
            m,s=pty.openpty(); masters[name]=m; slaves[name]=s; kwargs[name]=s
        else:
            kwargs[name]=subprocess.PIPE
    p=subprocess.Popen(args, stdin=kwargs['stdin'], stdout=kwargs['stdout'], stderr=kwargs['stderr'], close_fds=True)
    for s in slaves.values(): os.close(s)
    # if stdin pipe, send inp; if stdin tty, send via master
    if stream_tty.get('stdin'):
        if inp: os.write(masters['stdin'], inp)
        # close? keep?
    out_pipe = p.stdout.read() if not stream_tty.get('stdout') and p.stdout else b""
    err_pipe = p.stderr.read() if not stream_tty.get('stderr') and p.stderr else b""
    # wait - need timeout logic simplistic: if stdin tty, p may wait for input; but for these args it won't read stdin (file input) or will read tty stdin: for no-input it exits. Use communicate alternative? We're manual.
    try:
        p.wait(timeout=2)
    except subprocess.TimeoutExpired:
        p.kill(); p.wait()
        print(stream_tty,args,"TIMEOUT")
    def readmaster(name):
        data=b""
        fd=masters[name]
        while True:
            r,_,_=select.select([fd],[],[],0.1)
            if not r: break
            try: chunk=os.read(fd,4096)
            except OSError: break
            if not chunk: break
            data+=chunk
        return data
    out_tty=readmaster('stdout') if stream_tty.get('stdout') else b""
    err_tty=readmaster('stderr') if stream_tty.get('stderr') else b""
    for m in masters.values(): os.close(m)
    print("TTY",stream_tty,"args",args,"exit",p.returncode)
    print(" stdout_pipe",out_pipe," stdout_tty",out_tty)
    print(" stderr_pipe",err_pipe," stderr_tty",err_tty)

