use clap::{Parser, CommandFactory};
use clap_complete::{generate, Generator, Shell};
use std::io;
#[derive(Parser, Debug)]
#[command(version, about = "A CLI wrapping the Melody language compiler", long_about = None)]
struct Args {
    /// Read from a file
    /// Use '-' and or pipe input to read from stdin
    #[arg(value_name="INPUT_FILE_PATH")]
    input: Option<String>,
    /// Write to a file
    #[arg(short, long, value_name="OUTPUT_FILE_PATH", conflicts_with="generate_completions", conflicts_with="test", conflicts_with="test_file")]
    output: Option<String>,
    /// Print output with no color
    #[arg(short, long)]
    no_color: bool,
    /// Start the Melody REPL
    #[arg(short, long, conflicts_with="generate_completions")]
    repl: bool,
    /// Outputs completions for the selected shell
    /// To use, write the output to the appropriate location for your shell
    #[arg(long="generate-completions", value_name="completions")]
    generate_completions: Option<String>,
    /// Test the compiled regex against a string
    #[arg(short, long, value_name="test", conflicts_with="test_file")]
    test: Option<String>,
    /// Test the compiled regex against the contents of a file
    #[arg(short, long="test-file", value_name="test-file")]
    test_file: Option<String>,
}
fn print_completions<G: Generator>(gen: G, cmd: &mut clap::Command) { generate(gen, cmd, "melody", &mut io::stdout()); }
fn main() {
    let args = Args::parse();
    if let Some(sh)=args.generate_completions {
        let mut cmd = Args::command();
        match sh.as_str() {
            "bash" => print_completions(Shell::Bash, &mut cmd),
            "zsh" => print_completions(Shell::Zsh, &mut cmd),
            "fish" => print_completions(Shell::Fish, &mut cmd),
            "elvish" => print_completions(Shell::Elvish, &mut cmd),
            "powershell" => print_completions(Shell::PowerShell, &mut cmd),
            _ => {}
        }
        return;
    }
    println!("{:?}", args);
}
RS
cd /tmp/prot && cargo build --offline 2>&1 | tail -20"}

