#!/usr/bin/env python3
import os
import sys
import signal

try:
    signal.signal(signal.SIGINT, signal.SIG_DFL)
except Exception:
    pass

VERSION_STR = "melody_cli 0.20.0"

# ---------------------------------------------------------------- colors
def _env_present(name):
    return name in os.environ

def _env_val(name):
    return os.environ.get(name)

def app_color_enabled(no_color_flag=False, stream_stdout=None):
    # colored crate ShouldColorize::from_env with manual override for -n
    if no_color_flag:
        return False
    # resolve_clicolor_force
    # CLICOLOR_FORCE present (env::var Ok) and != "0" -> True
    if _env_present("CLICOLOR_FORCE"):
        v = _env_val("CLICOLOR_FORCE")
        # env::var fails on non-unicode; python uses surrogateescape; treat surrogates as not present-ish
        if v is not None and "\udc80" not in v and not any(0xDC80 <= ord(c) <= 0xDCFF for c in v):
            if v != "0":
                return True
    if _env_present("NO_COLOR"):
        v = _env_val("NO_COLOR")
        if v is not None and not any(0xDC80 <= ord(c) <= 0xDCFF for c in v):
            return False
    clicolor = True
    if _env_present("CLICOLOR"):
        v = _env_val("CLICOLOR")
        if v is not None and not any(0xDC80 <= ord(c) <= 0xDCFF for c in v):
            clicolor = (v != "0")
    is_tty = False
    try:
        is_tty = sys.stdout.isatty()
    except Exception:
        is_tty = False
    return bool(clicolor and is_tty)

def clap_color_enabled(is_tty_stream):
    # anstream / anstyle-query choice
    # no_color: non-empty
    v = os.environ.get("NO_COLOR")
    if v:
        return False
    v = os.environ.get("CLICOLOR_FORCE")
    if v:  # non-empty (any value incl "0")
        return True
    # clicolor
    clicolor_present = "CLICOLOR" in os.environ
    clicolor_val = os.environ.get("CLICOLOR")
    clicolor_enabled = False
    clicolor_disabled = False
    if clicolor_present:
        # anstyle: Some(value != "0")
        if clicolor_val == "0":
            clicolor_disabled = True
        else:
            clicolor_enabled = True
    if clicolor_disabled:
        return False
    if not is_tty_stream:
        return False
    term = os.environ.get("TERM")
    term_supports = term is not None and term != "dumb"
    is_ci = "CI" in os.environ
    return bool(term_supports or clicolor_enabled or is_ci)

class Color:
    def __init__(self, enabled):
        self.enabled = enabled
    def wrap(self, code, s):
        if not self.enabled:
            return s
        return f"\x1b[{code}m{s}\x1b[0m"
    def bright_blue(self, s):
        return self.wrap(94, s)
    def bright_red(self, s):
        return self.wrap(91, s)
    def bright_green(self, s):
        return self.wrap(92, s)
    def dim(self, s):
        return self.wrap(2, s)

def write_stdout(s):
    # s: str
    data = s.encode('utf-8', 'surrogateescape')
    try:
        os.write(1, data)
    except BrokenPipeError:
        # mimic Rust println panic (approx)
        try:
            os.write(2, b"thread 'main' panicked at std/src/io/stdio.rs:1117:9:\nfailed printing to stdout: Broken pipe (os error 32)\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        except Exception:
            pass
        os._exit(101)
    except OSError:
        # let python handle other errors as exception upstream if needed
        raise

def write_stderr(s):
    data = s.encode('utf-8', 'surrogateescape')
    try:
        os.write(2, data)
    except BrokenPipeError:
        try:
            os.write(2, b"thread 'main' panicked at std/src/io/stdio.rs:1117:9:\nfailed printing to stderr: Broken pipe (os error 32)\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        except Exception:
            pass
        os._exit(101)

