# ---------------------------------------------------------------- clap-like CLI

LONG_ARGS = {
    "output": {"id": "output", "display": "--output <OUTPUT_FILE_PATH>", "kind": "value", "long": "output", "short": "o", "value_name": "OUTPUT_FILE_PATH"},
    "no-color": {"id": "no-color", "display": "--no-color", "kind": "flag", "long": "no-color", "short": "n"},
    "repl": {"id": "repl", "display": "--repl", "kind": "flag", "long": "repl", "short": "r"},
    "generate-completions": {"id": "completions", "display": "--generate-completions <completions>", "kind": "value", "long": "generate-completions", "value_name": "completions"},
    "test": {"id": "test", "display": "--test <test>", "kind": "value", "long": "test", "short": "t", "value_name": "test"},
    "test-file": {"id": "test-file", "display": "--test-file <test-file>", "kind": "value", "long": "test-file", "short": "f", "value_name": "test-file"},
    "help": {"id": "help", "display": "--help", "kind": "help", "long": "help", "short": "h"},
    "version": {"id": "version", "display": "--version", "kind": "version", "long": "version", "short": "V"},
}
SHORT_ARGS = {}
for _spec in LONG_ARGS.values():
    if "short" in _spec:
        SHORT_ARGS[_spec["short"]] = _spec
ID_ARGS = {}
for _spec in LONG_ARGS.values():
    ID_ARGS[_spec["id"]] = _spec
ID_ARGS["input"] = {"id": "input", "display": "[INPUT_FILE_PATH]", "kind": "positional", "long": None}

# conflict pairs (undirected) by id
CONFLICT_PAIRS = {
    ("output", "completions"), ("output", "test"), ("output", "test-file"),
    ("repl", "completions"), ("repl", "test"), ("repl", "test-file"),
    ("completions", "test"), ("completions", "test-file"), ("completions", "input"),
    ("test", "test-file"),
}
def conflicts_with(a, b):
    return (a, b) in CONFLICT_PAIRS or (b, a) in CONFLICT_PAIRS

def bin_name():
    argv0 = sys.argv[0] if sys.argv else "executable"
    # clap uses file name component
    base = os.path.basename(argv0)
    return base if base else "executable"

HELP_TEMPLATE = """A CLI wrapping the Melody language compiler

Usage: {bin} [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
"""

def render_help(bname, colored):
    text = HELP_TEMPLATE.replace("{bin}", bname)
    if not colored:
        return text
    # style like clap
    out_lines = []
    lines = text.split("\n")
    # We will construct styled version line by line
    for line in lines:
        if line.startswith("Usage: "):
            rest = line[len("Usage: "):]
            # rest starts with bname
            if rest.startswith(bname):
                rest = "\x1b[1m" + bname + "\x1b[0m" + rest[len(bname):]
            out_lines.append("\x1b[1m\x1b[4mUsage:\x1b[0m " + rest)
        elif line in ("Arguments:", "Options:"):
            out_lines.append("\x1b[1m\x1b[4m" + line + "\x1b[0m")
        elif line.startswith("  -") or line.startswith("      --"):
            # bold short/long names
            # formats: "  -o, --output ..."  "  -n, ..." "      --generate..."
            s = line
            # process segments
            # Use manual parsing
            styled = ""
            i = 0
            # leading spaces
            while i < len(s) and s[i] == ' ':
                styled += ' '; i += 1
            # now tokens until value/help separation
            # short form?
            if i < len(s) and s[i] == '-':
                # capture -x or --long
                j = i
                while j < len(s) and s[j] not in (' ', ','):
                    j += 1
                styled += "\x1b[1m" + s[i:j] + "\x1b[0m"
                i = j
                # comma etc
                while i < len(s) and s[i] in (',', ' '):
                    # if next is --long, handle below; preserve spaces/comma but stop before '-'
                    if s[i] == ',' :
                        styled += ','; i += 1
                    else:
                        # look ahead: spaces before -- ?
                        # accumulate spaces
                        k = i
                        while k < len(s) and s[k] == ' ':
                            k += 1
                        if k < len(s) and s[k] == '-':
                            styled += s[i:k]; i = k; break
                        else:
                            styled += s[i:]; i = len(s); break
                if i < len(s) and s[i] == '-':
                    j = i
                    while j < len(s) and s[j] not in (' ', ','):
                        j += 1
                    styled += "\x1b[1m" + s[i:j] + "\x1b[0m"
                    i = j
                styled += s[i:]
                out_lines.append(styled)
            else:
                out_lines.append(line)
        else:
            out_lines.append(line)
    return "\n".join(out_lines)

def clap_error_exit(message_parts):
    # message_parts already rendered (without trailing?); caller handles
    raise SystemExit(2)

class ClapExit(Exception):
    def __init__(self, code, stdout_text="", stderr_text=""):
        self.code = code
        self.stdout_text = stdout_text
        self.stderr_text = stderr_text

def _styled_clap(is_stderr=True):
    is_tty = False
    try:
        is_tty = sys.stderr.isatty() if is_stderr else sys.stdout.isatty()
    except Exception:
        is_tty = False
    return clap_color_enabled(is_tty)

def format_usage(bname, kind, arg_id=None, colored=False, used_ids=None):
    # returns "Usage: ..." without trailing newline, styled if colored
    label = "\x1b[1m\x1b[4mUsage:\x1b[0m" if colored else "Usage:"
