def format_pest_error(parser):
    text = parser.text
    pos = parser.attempt_pos
    # clamp
    if pos < 0:
        pos = 0
    if pos > len(text):
        pos = len(text)
    positives = sorted(set(parser.pos_attempts), key=lambda r: RULE_ORDER.get(r, 999))
    negatives = sorted(set(parser.neg_attempts), key=lambda r: RULE_ORDER.get(r, 999))
    # line/col like pest Position::line_col (char based)
    line = 1; col = 1
    i = 0
    slice_chars = text[:pos]
    idx = 0
    while idx < len(slice_chars):
        c = slice_chars[idx]
        if c == '\r':
            if idx + 1 < len(slice_chars) and slice_chars[idx+1] == '\n':
                idx += 2; line += 1; col = 1
            else:
                idx += 1; col += 1
        elif c == '\n':
            idx += 1; line += 1; col = 1
        else:
            idx += 1; col += 1
    # line_of
    # find line start: last '\n' with index < pos
    line_start = 0
    for j in range(min(pos, len(text))):
        if text[j] == '\n':
            line_start = j + 1
    # find line end: first '\n' at or after pos, include it; else len
    line_end = len(text)
    for j in range(pos, len(text)):
        if text[j] == '\n':
            line_end = j + 1
            break
    line_raw = text[line_start:line_end]
    if pos < len(text) and text[pos] in ('\n', '\r'):
        line_display = line_raw.replace('\r', '␍').replace('\n', '␊')
    else:
        line_display = line_raw.replace('\r', '').replace('\n', '')
    spacing = ' ' * len(str(line))
    # underline
    underline_chars = []
    for c in line_display[:col-1]:
        if c == '\t':
            underline_chars.append('\t')
        else:
            underline_chars.append(' ')
    underline = ''.join(underline_chars) + '^---'
    def enumerate_rules(rules):
        if len(rules) == 1:
            return rules[0]
        elif len(rules) == 2:
            return f"{rules[0]} or {rules[1]}"
        else:
            return ", ".join(rules[:-1]) + f", or {rules[-1]}"
    if negatives and positives:
        message = f"unexpected {enumerate_rules(negatives)}; expected {enumerate_rules(positives)}"
