    elif positives:
        message = f"expected {enumerate_rules(positives)}"
    else:
        message = "unknown parsing error"
    return f"{spacing}--> {line}:{col}\n{spacing} |\n{line} | {line_display}\n{spacing} | {underline}\n{spacing} |\n{spacing} = {message}"

