# ---------------------------------------------------------------- runtime

def print_app_error(msg, appcol):
    # msg may be multi-line; color wraps whole "Error: {msg}"
    text = f"Error: {msg}"
    if appcol.enabled:
        text = appcol.bright_red(text)
    write_stderr(text + "\n")

def do_repl(appcol):
    # banner
    # colors: bright green 92, bright blue 94, bright red 91, dim 2
    def g(s): return appcol.bright_green(s)
    def b(s): return appcol.bright_blue(s)
    def r(s): return appcol.bright_red(s)
    banner_lines = [
        g("Melody REPL v0.20.0"),
        "",
        g("Commands:"),
        "",
        f"- {b(':u, :undo')} - {g('undo the latest line')}",
        f"- {b(':r, :redo')} - {g('redo the latest undo')}",
        f"- {b(':c, :clear')} - {g('clear all REPL history and previous input')}",
        f"- {b(':s, :source')} - {g('print all previously entered lines')}",
        f"- {b(':e, :exit')} - {g('exit the REPL')}",
        "",
    ]
    write_stdout("\n".join(banner_lines) + "\n")
    lines = []
    undone = []
    # use buffer for reading to detect invalid utf-8
    input_buffer = sys.stdin.buffer
    output_flush = lambda: None
    def compile_current():
        src = "\n".join(lines)
        return compile_melody(src)
    while True:
        write_stdout(b("~ "))
        # flush via os.write already unbuffered
        try:
            raw_line = input_buffer.readline()
        except OSError:
            write_stdout(r("Error: unable to read input") + "\n") if False else write_stderr("")
            # original: printed to stdout? in pty merged. It was likely eprintln? Let's check stream separation later. Use stderr? We'll handle below
            return 74
        if raw_line == b"":
            # EOF: treat as empty line (like Rust read_line returning 0 and continuing)
            # But if stdin is EOF repeatedly, this could loop; original does same on Ctrl-D.
            # To avoid infinite loop when the pty / stdin is actually closed and stdout is a pipe (repl would not start in that case)
            # In a tty, Ctrl-D yields this once per keypress and terminal remains open for next read.
            line = ""
            is_eof = True
        else:
            is_eof = False
            try:
                line = raw_line.decode('utf-8')
            except UnicodeDecodeError:
                # print error: original printed (merged) red Error: unable to read input and exited 74
                # Determine stream: we will write to stdout? Let's write to stderr? Need check; for now write as app error to stderr using write_stdout? 
                # We use write_stdout to match pty merged, but later separation test may reveal. Use write_stderr in final version? 
                # placeholder: write to stdout via print_app_error equivalent but without? We'll write red to stderr ( Rust eprintln likely)
                msg = "Error: unable to read input"
                if appcol.enabled:
                    msg = appcol.bright_red(msg)
                write_stdout(msg + "\n")
                return 74
        # process line: trim_end in Rust (Pattern_White_Space)
        # readline includes trailing \n (and possibly \r? terminal gives \n)
        trimmed = line.rstrip(RUST_WS) if not is_eof else ""
        # Rust read_line: if EOF with no bytes, input is "" trimmed = ""
        if not is_eof:
            # command check uses trimmed (trim_end)
            if trimmed.startswith(":"):
                cmd = trimmed
                if cmd in (":e", ":exit"):
                    write_stdout(g("exit") + "\n")
                    return 0
                elif cmd in (":u", ":undo"):
                    if not lines:
                        # red message with internal newline
                        msg_text = "nothing to undo\n"
                        out = appcol.bright_red(msg_text) if appcol.enabled else msg_text
                        write_stdout(out + "\n")
                    else:
                        write_stdout(g("undo") + "\n")
                        popped = lines.pop()
                        undone.append(popped)
                        if lines:
                            try:
                                compiled = compile_current()
                            except MelodyError:
                                compiled = ""
                            write_stdout(b(compiled) + "\n")
                        write_stdout("\n")
                    continue
                elif cmd in (":r", ":redo"):
                    if not undone:
                        msg_text = "nothing to redo\n"
                        out = appcol.bright_red(msg_text) if appcol.enabled else msg_text
                        write_stdout(out + "\n")
                    else:
                        write_stdout(g("redo") + "\n")
                        restored = undone.pop()
                        lines.append(restored)
