                            compiled = compile_current()
                        except MelodyError:
                            compiled = ""
                        write_stdout(b(compiled) + "\n")
                        write_stdout("\n")
                    continue
                elif cmd in (":c", ":clear"):
                    lines.clear(); undone.clear()
                    write_stdout(g("clear") + "\n")
                    write_stdout("\n")
